package com.primehr.rsp.selection.application;
import com.fasterxml.jackson.core.JsonProcessingException;import com.fasterxml.jackson.databind.ObjectMapper;import com.primehr.rsp.applicant.domain.PositionApplication;import com.primehr.rsp.evaluation.domain.*;import com.primehr.rsp.evaluation.infrastructure.*;import com.primehr.rsp.selection.api.SelectionDtos.*;import com.primehr.rsp.selection.domain.*;import com.primehr.rsp.selection.infrastructure.*;import com.primehr.shared.api.PageResponse;import com.primehr.shared.audit.PrimeHrAuditService;import com.primehr.shared.exception.*;import org.springframework.data.domain.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.nio.charset.StandardCharsets;import java.security.*;import java.time.Instant;import java.util.*;import java.util.function.Function;import java.util.stream.Collectors;
@Service @Transactional public class SelectionServiceImpl implements SelectionService{
 private final SelectionCaseRepository cases;private final SelectionCandidateDecisionRepository decisions;private final SelectionNoticeRepository notices;private final OfferResponseRepository offers;private final EvaluationProceedingRepository proceedings;private final EvaluationCandidateRepository candidates;private final ComparativeEvaluationRepository comparisons;private final ComparativeEvaluationItemRepository items;private final HrmpsbMeetingRepository meetings;private final HrmpsbResolutionRepository resolutions;private final PrimeHrAuditService audit;private final ObjectMapper json;
 public SelectionServiceImpl(SelectionCaseRepository a,SelectionCandidateDecisionRepository b,SelectionNoticeRepository c,OfferResponseRepository d,EvaluationProceedingRepository e,EvaluationCandidateRepository f,ComparativeEvaluationRepository g,ComparativeEvaluationItemRepository h,HrmpsbMeetingRepository i,HrmpsbResolutionRepository j,PrimeHrAuditService k,ObjectMapper l){cases=a;decisions=b;notices=c;offers=d;proceedings=e;candidates=f;comparisons=g;items=h;meetings=i;resolutions=j;audit=k;json=l;}
 @Override @Transactional(readOnly=true)public PageResponse<CaseResponse>list(String agency,int page,int size){return PageResponse.from(cases.findByAgencyIdOrderByCreatedAtDesc(agency,PageRequest.of(page,Math.min(Math.max(size,1),100))),this::response);}
 @Override @Transactional(readOnly=true)public CaseResponse get(String agency,String id){return response(selection(agency,id));}
 @Override public CaseResponse create(String agency,CreateSelection r,String actor,String correlation){EvaluationProceeding p=proceedings.findByIdAndAgencyId(r.proceedingId(),agency).orElseThrow(()->new ResourceNotFoundException("Finalized evaluation proceeding was not found"));if(p.getStatus()!=EvaluationProceeding.Status.FINALIZED)throw new ApplicationConflictException("Selection requires a FINALIZED evaluation proceeding");EvaluationProceeding latest=proceedings.findByAgencyIdAndPublicationIdOrderByCreatedAtDesc(agency,p.getPublication().getId()).stream().findFirst().orElseThrow();if(!latest.getId().equals(p.getId()))throw new ApplicationConflictException("Selection requires the latest evaluation proceeding for the publication");if(cases.findByAgencyIdAndCurrentPublicationKey(agency,p.getPublication().getId()).isPresent())throw new ApplicationConflictException("A current selection case already exists for this publication");return createFromSource(agency,p,null,r.assignedApproverEmployeeNo(),r.offerResponseDeadline(),r.selectedSafeText(),r.nonSelectedSafeText(),actor,correlation);}
 @Override public CaseResponse decide(String agency,String id,DecideSelection r,String actor,String correlation){SelectionCase value=selection(agency,id);version(value.getVersion(),r.recordVersion());List<SelectionCandidateDecision> set=decisions.findByAgencyIdAndSelectionCaseIdOrderByRankNumberAsc(agency,id);for(SelectionCandidateDecision candidate:set)candidate.clearSelection();if(r.outcome()==SelectionCase.Outcome.SELECTED){SelectionCandidateDecision selected=set.stream().filter(c->c.getCandidateId().equals(r.selectedCandidateId())).findFirst().orElseThrow(()->new ApplicationConflictException("Selected candidate is outside the finalized evaluated set"));EvaluationCandidate source=candidates.findByIdAndAgencyId(selected.getCandidateId(),agency).orElseThrow();if(source.getApplication().getStatus()!=PositionApplication.Status.QUALIFIED)throw new ApplicationConflictException("Selected candidate is no longer qualified or has withdrawn");if(selected.isExcluded())throw new ApplicationConflictException("A mandatory-gate excluded candidate cannot be selected");boolean variance=selected.getRecommendation()!=HrmpsbResolution.Recommendation.ENDORSED_FOR_SELECTION_DECISION;if(variance&&(blank(r.varianceBasis())||blank(r.varianceReason())))throw new ApplicationConflictException("A non-endorsed selection requires legal/policy basis and reason");if(!variance&&(!blank(r.varianceBasis())||!blank(r.varianceReason())))throw new IllegalArgumentException("Variance fields are valid only for a non-endorsed selection");selected.select();}value.decide(r.outcome(),r.selectedCandidateId(),r.reason(),r.varianceBasis(),r.varianceReason(),r.reviewDate());decisions.saveAll(set);value=cases.saveAndFlush(value);audit.record(agency,"DECIDE_SELECTION_CASE","RSP_SELECTION_CASE",id,value.getCaseRevision(),value.getVersion(),null,response(value),r.reason(),correlation);return response(value);}
 @Override public CaseResponse transition(String agency,String id,Transition r,String actor,String action,boolean administrator,String correlation){SelectionCase value=selection(agency,id);version(value.getVersion(),r.recordVersion());switch(action){case"submit"->value.submit(actor,Instant.now());case"approve"->value.approve(actor,administrator,r.administratorExceptionReason(),Instant.now());case"return"->value.returnForCorrection(actor,r.reason(),Instant.now());case"finalize"->{value.finalizeCase(actor,Instant.now());releaseNotices(value);}case"cancel"->value.cancel(r.reason());default->throw new IllegalArgumentException("Selection action is invalid");}value=cases.saveAndFlush(value);audit.record(agency,action.toUpperCase(Locale.ROOT)+"_SELECTION_CASE","RSP_SELECTION_CASE",id,value.getCaseRevision(),value.getVersion(),null,response(value),r.reason(),correlation);return response(value);}
 @Override public CaseResponse successor(String agency,String id,Successor r,String actor,String correlation){SelectionCase prior=selection(agency,id);version(prior.getVersion(),r.recordVersion());if(offers.findByAgencyIdAndSelectionCaseId(agency,id).filter(o->o.getStatus()==OfferResponse.Status.ACCEPTED).isPresent())throw new ApplicationConflictException("An accepted offer cannot be superseded by selection correction");prior.supersede();List<SelectionNotice> oldNotices=notices.findByAgencyIdAndSelectionCaseId(agency,id);oldNotices.forEach(SelectionNotice::supersede);notices.saveAll(oldNotices);cases.saveAndFlush(prior);EvaluationProceeding p=proceedings.findByIdAndAgencyId(prior.getProceedingId(),agency).orElseThrow();return createFromSource(agency,p,prior,r.assignedApproverEmployeeNo(),r.offerResponseDeadline(),r.selectedSafeText(),r.nonSelectedSafeText(),actor,correlation);}
 @Override public ApplicantSelectionStatus applicantStatus(String agency,String applicant,String application){SelectionNotice notice=notices.findByAgencyIdAndApplicationIdAndApplicantIdAndCurrentNoticeKeyIsNotNull(agency,application,applicant).orElseThrow(()->new ResourceNotFoundException("No released selection notice exists for this application"));OfferResponse offer=offers.findByAgencyIdAndApplicationIdAndApplicantId(agency,application,applicant).orElse(null);if(offer!=null&&offer.expire(Instant.now()))offer=offers.saveAndFlush(offer);return applicantResponse(notice,offer);}
 @Override public ApplicantSelectionStatus applicantRespond(String agency,String applicant,String application,ApplicantOfferResponse r,String correlation){SelectionNotice notice=notices.findByAgencyIdAndApplicationIdAndApplicantIdAndCurrentNoticeKeyIsNotNull(agency,application,applicant).orElseThrow(()->new ResourceNotFoundException("No released selection notice exists for this application"));if(notice.getKind()!=SelectionNotice.Kind.SELECTED)throw new ApplicationConflictException("Only the selected applicant may respond to an offer");OfferResponse offer=offers.findByAgencyIdAndApplicationIdAndApplicantId(agency,application,applicant).orElseThrow(()->new ResourceNotFoundException("Offer was not found"));if(offer.expire(Instant.now())){offer=offers.saveAndFlush(offer);return applicantResponse(notice,offer);}offer.respond(r.response(),r.idempotencyKey(),r.comment(),Instant.now());offer=offers.saveAndFlush(offer);audit.record(agency,"RESPOND_TO_SELECTION_OFFER","RSP_OFFER_RESPONSE",offer.getId(),null,offer.getVersion(),null,Map.of("status",offer.getStatus().name()),null,correlation);return applicantResponse(notice,offer);}
 private CaseResponse createFromSource(String agency,EvaluationProceeding p,SelectionCase prior,String approver,Instant deadline,String selectedText,String nonSelectedText,String actor,String correlation){ComparativeEvaluation comparison=comparisons.findByAgencyIdAndProceedingIdAndStatus(agency,p.getId(),ComparativeEvaluation.Status.FINALIZED).orElseThrow(()->new ApplicationConflictException("A finalized comparative evaluation is required"));HrmpsbMeeting meeting=meetings.findByAgencyIdAndProceedingIdOrderByMeetingRevisionAsc(agency,p.getId()).stream().filter(m->m.getStatus()==HrmpsbMeeting.Status.FINALIZED).reduce((a,b)->b).orElseThrow(()->new ApplicationConflictException("A finalized HRMPSB meeting is required"));Map<String,HrmpsbResolution> resolutionMap=resolutions.findByAgencyIdAndMeetingId(agency,meeting.getId()).stream().collect(Collectors.toMap(HrmpsbResolution::getCandidateId,Function.identity()));Map<String,EvaluationCandidate> candidateMap=candidates.findByAgencyIdAndProceedingIdOrderByAdmittedAtAsc(agency,p.getId()).stream().collect(Collectors.toMap(EvaluationCandidate::getId,Function.identity()));List<ComparativeEvaluationItem> evaluationItems=items.findByAgencyIdAndComparativeEvaluationIdOrderByRankNumberAsc(agency,comparison.getId());if(evaluationItems.size()!=candidateMap.size()||resolutionMap.size()!=candidateMap.size())throw new ApplicationConflictException("Finalized comparison and HRMPSB resolution evidence must cover every candidate");Map<String,Object> snapshot=new LinkedHashMap<>();snapshot.put("proceedingId",p.getId());snapshot.put("proceedingVersion",p.getVersion());snapshot.put("publicationId",p.getPublication().getId());snapshot.put("vacancyFingerprint",p.getVacancyFingerprint());snapshot.put("comparativeEvaluationId",comparison.getId());snapshot.put("comparativeFingerprint",comparison.getCalculationFingerprint());snapshot.put("meetingId",meeting.getId());snapshot.put("meetingRevision",meeting.getMeetingRevision());snapshot.put("candidateIds",evaluationItems.stream().map(ComparativeEvaluationItem::getCandidateId).toList());String serialized=json(snapshot);int revision=Math.toIntExact(cases.countByAgencyIdAndProceedingId(agency,p.getId())+1);SelectionCase value=cases.saveAndFlush(new SelectionCase(agency,p.getId(),p.getPublication().getId(),comparison.getId(),comparison.getCalculationFingerprint(),meeting.getId(),revision,prior==null?null:prior.getId(),approver,deadline,selectedText,nonSelectedText,serialized,sha256(serialized)));List<SelectionCandidateDecision> frozen=new ArrayList<>();for(ComparativeEvaluationItem item:evaluationItems){EvaluationCandidate candidate=Optional.ofNullable(candidateMap.get(item.getCandidateId())).orElseThrow(()->new ApplicationConflictException("Comparative candidate source is stale"));HrmpsbResolution resolution=Optional.ofNullable(resolutionMap.get(item.getCandidateId())).orElseThrow(()->new ApplicationConflictException("Candidate resolution is missing"));frozen.add(new SelectionCandidateDecision(agency,value.getId(),candidate.getId(),candidate.getApplication().getId(),candidate.getApplicantId(),item.getTotalScore(),item.getRankNumber(),item.getTieGroup(),item.isExcluded(),item.getExclusionReason(),resolution.getRecommendation(),resolution.getReason()));}decisions.saveAll(frozen);audit.record(agency,prior==null?"CREATE_SELECTION_CASE":"CREATE_SELECTION_SUCCESSOR","RSP_SELECTION_CASE",value.getId(),revision,value.getVersion(),null,response(value),prior==null?null:"Controlled correction successor",correlation);return response(value);}
 private void releaseNotices(SelectionCase value){List<SelectionCandidateDecision> set=decisions.findByAgencyIdAndSelectionCaseIdOrderByRankNumberAsc(value.getAgencyId(),value.getId());for(SelectionCandidateDecision candidate:set){SelectionNotice.Kind kind;String text;if(value.getOutcome()==SelectionCase.Outcome.SELECTED){kind=candidate.isSelected()?SelectionNotice.Kind.SELECTED:SelectionNotice.Kind.NOT_SELECTED;text=candidate.isSelected()?value.getSelectedSafeText():value.getNonSelectedSafeText();}else if(value.getOutcome()==SelectionCase.Outcome.NO_SELECTION){kind=SelectionNotice.Kind.NO_SELECTION;text=value.getNonSelectedSafeText();}else{kind=SelectionNotice.Kind.DEFERRED;text=value.getNonSelectedSafeText();}notices.save(new SelectionNotice(value.getAgencyId(),value.getId(),candidate.getApplicationId(),candidate.getApplicantId(),kind,text,Instant.now()));if(candidate.isSelected())offers.save(new OfferResponse(value.getAgencyId(),value.getId(),candidate.getApplicationId(),candidate.getApplicantId(),value.getOfferResponseDeadline()));}}
 private SelectionCase selection(String agency,String id){return cases.findByIdAndAgencyId(id,agency).orElseThrow(()->new ResourceNotFoundException("Selection case was not found"));}private static void version(long actual,long expected){if(actual!=expected)throw new OptimisticConflictException("Selection record version changed");}private static boolean blank(String value){return value==null||value.isBlank();}private String json(Object value){try{return json.writeValueAsString(value);}catch(JsonProcessingException e){throw new IllegalStateException("Selection source snapshot could not be serialized",e);}}private static String sha256(String value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
 private CaseResponse response(SelectionCase v){List<CandidateResponse> cs=decisions.findByAgencyIdAndSelectionCaseIdOrderByRankNumberAsc(v.getAgencyId(),v.getId()).stream().map(c->new CandidateResponse(c.getId(),c.getCandidateId(),c.getApplicationId(),c.getApplicantId(),c.getTotalScore(),c.getRankNumber(),c.getTieGroup(),c.isExcluded(),c.getExclusionReason(),c.getRecommendation().name(),c.getRecommendationReason(),c.isSelected(),c.getVersion())).toList();return new CaseResponse(v.getId(),v.getProceedingId(),v.getPublicationId(),v.getComparativeEvaluationId(),v.getComparativeFingerprint(),v.getMeetingId(),v.getCaseRevision(),v.getSupersedesId(),v.getStatus().name(),v.getOutcome()==null?null:v.getOutcome().name(),v.getSelectedCandidateId(),v.getAssignedApproverEmployeeNo(),v.getDecisionReason(),v.getVarianceBasis(),v.getVarianceReason(),v.getReviewDate(),v.getOfferResponseDeadline(),v.getSourceFingerprint(),v.getSubmittedBy(),v.getSubmittedAt(),v.getApprovedBy(),v.getApprovedAt(),v.getFinalizedBy(),v.getFinalizedAt(),v.getReturnReason(),v.getAdministratorExceptionReason(),v.getVersion(),cs);}
 private static ApplicantSelectionStatus applicantResponse(SelectionNotice n,OfferResponse o){return new ApplicantSelectionStatus(n.getApplicationId(),n.getKind().name(),n.getSafeText(),n.getReleasedAt(),o==null?null:o.getResponseDeadline(),o==null?null:o.getStatus().name(),o==null?null:o.getRespondedAt(),o==null?0:o.getVersion());}
}
